def transform(grid):
    from collections import Counter, deque
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    cells={(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg}
    comps=[]
    while cells:
        seed=cells.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells:
                    cells.remove(p); comp.add(p); stack.append(p)
        comps.append(comp)
    template=max(comps,key=len)
    tr,tc=next(iter(template)); color=g[tr][tc]
    rs=[r for r,c in template]; cs=[c for r,c in template]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    th,tw=r1-r0+1,c1-c0+1
    outside={(r,c) for comp in comps if comp is not template for r,c in comp}
    center=next((r,c) for r,c in outside if g[r][c]==color)
    marker=g[center[0]][center[1]] if False else next(g[r][c] for r,c in outside if g[r][c]!=color)
    cr,cc=center
    up=(cr-min(r for r,c in outside))//2
    down=(max(r for r,c in outside)-cr)//2
    left=(cc-min(c for r,c in outside))//2
    right=(max(c for r,c in outside)-cr)//2
    out=[[bg]*w for _ in range(h)]
    for dr in range(-up,down+1):
        for dc in range(-left,right+1):
            for r,c in template:
                rr=r+dr*th; cc2=c+dc*tw
                if 0<=rr<h and 0<=cc2<w:
                    out[rr][cc2]=marker if dr==0 and dc==0 else color
    return out

